SELECT clock_timestamp() AS checked_at,jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl) ORDER BY p.oid::regprocedure::text) AS dependency_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND n.nspname='public' AND (p.proname IN ('can_access_inventory_branch','can_access_company_branch','current_staff_has_company_role','current_staff_id','enforce_inventory_item_scope','guard_purchase_request_line_supplier','validate_purchase_request_supplier_mappings') OR p.oid IN (SELECT t.tgfoid FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace WHERE ns.nspname='public' AND c.relname IN ('purchase_request_lines','purchase_request_unresolved_lines') AND NOT t.tgisinternal));
